      "CREATE INDEX `connectors_status` ON `connectors` (`status`);",
      "CREATE TABLE `connector_events` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`connector_id` text NOT NULL,\n\t`external_id` text NOT NULL,\n\t`topic` text NOT NULL,\n\t`received_at` integer NOT NULL,\n\t`status` text DEFAULT 'pending' NOT NULL,\n\t`item_id` text,\n\t`handled_at` integer,\n\t`error` text,\n\t`raw` text NOT NULL,\n\tFOREIGN KEY (`connector_id`) REFERENCES `connectors`(`id`) ON UPDATE no action ON DELETE no action\n);",
      "CREATE UNIQUE INDEX `connector_events_once` ON `connector_events` (`connector_id`,`external_id`);",
      "CREATE INDEX `connector_events_pending` ON `connector_events` (`status`,`received_at`);",
      "CREATE TABLE `webhooks` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`url` text NOT NULL,\n\t`secret_enc` text NOT NULL,\n\t`events` text NOT NULL,\n\t`payload_style` text DEFAULT 'thin' NOT NULL,\n\t`active` integer DEFAULT 1 NOT NULL,\n\t`failing_since` integer,\n\t`disabled_at` integer,\n\t`last_error` text,\n\t`created_at` integer NOT NULL,\n\t`updated_at` integer NOT NULL\n);",
